// ── Helpers ──

// Detect whether the teacher has actually written assessment content.
// Aligns with ensure-past empty-shell rows (Content='', Status='pending').
const hasLearningRecordBody = (record) => {
  if (!record) return false;
  return [record.Content, record.Progress, record.NextHomework, record.Comment, record.QuizScore]
    .some(v => String(v || '').trim() !== '');
};

const fillLabel = (record) => {
  const s = record?.Status;
  if (s === 'approved' || s === 'rejected') return '';
  return hasLearningRecordBody(record) ? '已填' : '未填';
};

const fillLabelClass = (record) => {
  const s = record?.Status;
  if (s === 'approved' || s === 'rejected') return '';
  return hasLearningRecordBody(record) ? 'fill-done' : 'fill-missing';
};

const statusLabel = (status) => {
  const map = { pending: '待審核', approved: '已核准', rejected: '已退回', changes_requested: '需修改' };
